let currentScreenId = '01';
let previousScreenId = '01';
let bottomPanelOpen = false;

window.BaraIDE = {
  topologyScope: 'proyecto',
  constructorMode: 'blueprint',
  jumpToLine(file, line) {
    renderScreen('03');
  }
};

function renderScreen(screenId) {
  if (screenId !== currentScreenId) {
    previousScreenId = currentScreenId;
  }
  currentScreenId = screenId;
  const screen = SCREENS[screenId] || SCREENS['01'];

  // Update Rail active link
  document.querySelectorAll('.rail a').forEach(a => {
    if (a.getAttribute('data-rail') === screen.rail) {
      a.classList.add('active');
    } else {
      a.classList.remove('active');
    }
  });

  // Update Demo label
  const labelEl = document.getElementById('demo-active-label');
  if (labelEl) labelEl.textContent = screen.label;

  // Update Demo menu selection
  document.querySelectorAll('.demo-option').forEach(opt => {
    if (opt.getAttribute('data-id') === screenId) {
      opt.classList.add('selected');
    } else {
      opt.classList.remove('selected');
    }
  });

  // Inject content
  const viewport = document.getElementById('screen-viewport');
  if (viewport) {
    let html = screen.html;

    // Screen 11 is screen 03 with bottom dock open
    if (screenId === '11') {
      bottomPanelOpen = true;
    } else if (screenId === '03' && bottomPanelOpen) {
      // show dock
      const dockHtml = SCREENS['11'].html.match(/<div id="bottom-dock".*?<\/div>\s*(?=<\/section>)/s);
      if (dockHtml) {
        html = html.replace('</section>', dockHtml[0] + '</section>');
      }
    }

    viewport.innerHTML = html;
    bindScreenInteractions();
  }
}

function toggleBottomPanel() {
  bottomPanelOpen = !bottomPanelOpen;
  if (bottomPanelOpen) {
    renderScreen('11');
  } else {
    if (currentScreenId === '11') {
      renderScreen('03');
    } else {
      renderScreen(currentScreenId);
    }
  }
}

function bindScreenInteractions() {
  // 1. Toast 05: Deshacer and Close (×)
  const deshacerBtn = document.getElementById('toast-deshacer-btn');
  if (deshacerBtn) {
    deshacerBtn.onclick = () => renderScreen('03');
  }
  const toastClose = document.getElementById('toast-close-btn');
  if (toastClose) {
    toastClose.onclick = () => {
      const t = document.querySelector('.toast');
      if (t) t.style.display = 'none';
    };
  }

  // 2. Banner 14: Close (×) returns to 03
  const bannerClose = document.getElementById('banner-nokey-close');
  if (bannerClose) {
    bannerClose.onclick = () => renderScreen('03');
  }

  // 3. Bottom dock controls
  const bpMin = document.getElementById('bp-btn-minimize');
  if (bpMin) {
    bpMin.onclick = () => toggleBottomPanel();
  }
  const bpClose = document.getElementById('bp-btn-close');
  if (bpClose) {
    bpClose.onclick = () => toggleBottomPanel();
  }
  const bpMax = document.getElementById('bp-btn-maximize');
  if (bpMax) {
    bpMax.onclick = () => {
      const dock = document.getElementById('bottom-dock');
      if (dock) {
        dock.style.height = dock.style.height === '380px' ? '240px' : '380px';
      }
    };
  }

  // 4. Bottom dock tabs
  ['problemas', 'registros', 'terminal'].forEach(tabName => {
    const tabEl = document.getElementById(`bp-tab-${tabName}`);
    if (tabEl) {
      tabEl.onclick = () => {
        document.querySelectorAll('.bp-tab').forEach(t => {
          t.style.background = 'transparent';
          t.style.color = 'var(--muted)';
          t.style.fontWeight = 'normal';
        });
        tabEl.style.background = 'var(--hover)';
        tabEl.style.color = '#fff';
        tabEl.style.fontWeight = '600';

        const content = document.getElementById('bp-content');
        if (content) {
          if (tabName === 'problemas') {
            content.innerHTML = `
              <div style="display:grid;grid-template-columns:180px 1fr 70px;gap:10px;padding:6px 12px;color:var(--muted);font-size:13px;border-bottom:1px solid var(--border2)">
                <span>archivo:línea</span><span>mensaje</span><span>nivel</span>
              </div>
              <div class="problem-row" onclick="window.BaraIDE.jumpToLine('HELLO.bara', 4)" style="display:grid;grid-template-columns:180px 1fr 70px;gap:10px;padding:8px 12px;border-bottom:1px solid var(--border2);font-size:14px;cursor:pointer;">
                <span class="mono" style="color:var(--green-soft)">HELLO.bara:4</span>
                <span>Identificador 'mostrar' — aviso de firma</span>
                <span style="color:#c9a227">aviso</span>
              </div>
              <div class="problem-row" onclick="window.BaraIDE.jumpToLine('genesis.bara', 12)" style="display:grid;grid-template-columns:180px 1fr 70px;gap:10px;padding:8px 12px;border-bottom:1px solid var(--border2);font-size:14px;cursor:pointer;">
                <span class="mono" style="color:var(--green-soft)">genesis.bara:12</span>
                <span>ContratoA no resuelto en alcance</span>
                <span style="color:#c45c5c">error</span>
              </div>
              <div class="problem-row" onclick="window.BaraIDE.jumpToLine('HELLO.bara', 2)" style="display:grid;grid-template-columns:180px 1fr 70px;gap:10px;padding:8px 12px;border-bottom:1px solid var(--border2);font-size:14px;cursor:pointer;">
                <span class="mono" style="color:var(--green-soft)">HELLO.bara:2</span>
                <span>Variable x sin anotación de tipo</span>
                <span style="color:var(--muted)">info</span>
              </div>
            `;
          } else if (tabName === 'registros') {
            content.innerHTML = `
              <div style="padding:10px 14px;font-family:var(--mono);font-size:13px;line-height:1.6;color:var(--text);">
                <div><span style="color:var(--muted)">10:31:02</span> <span style="color:var(--green-soft);font-weight:600">[INFO]</span> Carpeta abierta: genesis_engine</div>
                <div><span style="color:var(--muted)">10:31:04</span> <span style="color:var(--green-soft);font-weight:600">[INFO]</span> Kernel conectado · fa3d308</div>
                <div><span style="color:var(--muted)">10:31:40</span> <span style="color:#c9a227;font-weight:600">[AVISO]</span> Parche no verificado rechazado</div>
              </div>
            `;
          } else if (tabName === 'terminal') {
            content.innerHTML = `
              <div style="padding:10px 14px;font-family:var(--mono);font-size:14px;line-height:1.6;color:var(--text);">
                <span style="color:var(--green-soft)">bara-kernel$</span> ./bara --version<br/>
                Bara IDE v4.11<br/>
                <span style="color:var(--green-soft)">bara-kernel$</span> _
              </div>
            `;
          }
        }
      };
    }
  });

  // 5. Herramientas 07 cards
  document.querySelectorAll('.card').forEach(c => {
    const text = c.textContent || '';
    if (text.includes('Abrir carpeta') || text.includes('Nuevo archivo') || text.includes('genesis_engine')) {
      c.style.cursor = 'pointer';
      c.onclick = () => renderScreen('03');
    }
    if (text.includes('Constructor visual')) {
      c.style.cursor = 'pointer';
      c.onclick = () => renderScreen('08');
    }
    if (text.includes('Topología')) {
      c.style.cursor = 'pointer';
      c.onclick = () => renderScreen('09');
    }
    if (text.includes('Git')) {
      c.style.cursor = 'pointer';
      c.onclick = () => renderScreen('10');
    }
    if (text.includes('Problemas')) {
      c.style.cursor = 'pointer';
      c.onclick = () => renderScreen('11');
    }
    if (text.includes('Asistencia')) {
      c.style.cursor = 'pointer';
      c.onclick = () => alert('Se abre en ventana aparte');
    }
  });

  // 6. Buttons
  document.querySelectorAll('button').forEach(btn => {
    const t = (btn.textContent || '').trim();
    if (t === 'Nueva chat') btn.onclick = () => renderScreen('03');
    if (t === 'Aceptar' || t === 'Aceptar cambio') btn.onclick = () => renderScreen('05');
    if (t === 'Rechazar') btn.onclick = () => renderScreen('03');
    if (t === 'Deshacer') btn.onclick = () => renderScreen('03');
    if (t === 'Ir a Ajustes') btn.onclick = () => renderScreen('13');
    if (t === 'Abrir en el editor') btn.onclick = () => renderScreen('03');
    if (t === 'Cancelar') {
      btn.onclick = () => {
        document.querySelectorAll('.modal-backdrop').forEach(m => m.style.display = 'none');
      };
    }

    // Constructor buttons
    if (t === 'Ejemplo') {
      btn.onclick = () => {
        const b = document.getElementById('constructor-blueprint-code');
        if (b) {
          b.innerHTML = `<div>{</div><div>  "module": "lienzo_saludo",</div><div>  "label": "pipeline-saludo",</div><div>  "blocks": [</div><div>    {"id":"b1","name":"fuente_in","kind":"source",</div><div>     "arity":0,"ret":"number","hazard":0.0},</div><div>    {"id":"b2","name":"transformar_saludo","kind":"transform",</div><div>     "arity":1,"ret":"number","hazard":0.0,</div><div>     "inputs":[{"index":0,"type":"number"}]},</div><div>    {"id":"b3","name":"guardia_firma","kind":"guard",</div><div>     "arity":1,"ret":"number","hazard":0.0,</div><div>     "inputs":[{"index":1}]},</div><div>    {"id":"b4","name":"sumidero_out","kind":"sink",</div><div>     "arity":1,"ret":"void","hazard":0.0,</div><div>     "inputs":[{"index":2}]}</div><div>  ]</div><div>}</div>`;
        }
      };
    }
    if (t === 'Traducir y firmar') {
      btn.onclick = () => {
        document.querySelectorAll('label.row .check').forEach(c => {
          c.classList.add('on');
          c.textContent = '✓';
        });
      };
    }
    if (t.includes('Emitir .bara')) {
      btn.onclick = () => {
        const asideTitle = document.querySelector('#constructor-blueprint-aside > div');
        if (asideTitle) asideTitle.textContent = 'Código HELLO.bara';
        const b = document.getElementById('constructor-blueprint-code');
        if (b) {
          b.innerHTML = `<div><span style="color:#8fb89a">funcion</span> main() {</div><div>  variables x = 10</div><div>  <span style="color:#8fb89a">si</span> x &gt; 5 {</div><div>    mostrar("Bara IDE")</div><div>    registrar("ok")</div><div>  }</div><div>}</div>`;
        }
      };
    }
  });

  // 7. Topología scope selector (Proyecto | Bara)
  const scopeWrap = document.querySelector('div[style*="border-radius:999px"]');
  if (scopeWrap) {
    const tabs = scopeWrap.querySelectorAll('div');
    if (tabs.length === 2) {
      tabs[0].style.cursor = 'pointer';
      tabs[1].style.cursor = 'pointer';
      tabs[0].onclick = () => {
        window.BaraIDE.topologyScope = 'proyecto';
        tabs[0].style.background = 'var(--green-dim)';
        tabs[0].style.color = '#fff';
        tabs[0].style.fontWeight = '600';
        tabs[1].style.background = 'transparent';
        tabs[1].style.color = 'var(--muted)';
        tabs[1].style.fontWeight = 'normal';
      };
      tabs[1].onclick = () => {
        window.BaraIDE.topologyScope = 'bara';
        tabs[1].style.background = 'var(--green-dim)';
        tabs[1].style.color = '#fff';
        tabs[1].style.fontWeight = '600';
        tabs[0].style.background = 'transparent';
        tabs[0].style.color = 'var(--muted)';
        tabs[0].style.fontWeight = 'normal';
      };
    }
  }

  // 8. Command rows in Buscar (Screen 02)
  document.querySelectorAll('.main div').forEach(row => {
    if (row.style.border && row.textContent.includes('Ctrl+')) {
      row.style.cursor = 'pointer';
      row.onclick = () => {
        const txt = row.textContent;
        if (txt.includes('Abrir carpeta')) renderScreen('01');
        else if (txt.includes('Nuevo archivo')) renderScreen('03');
        else if (txt.includes('Chat asistente')) renderScreen('03');
        else if (txt.includes('Registros')) renderScreen('12');
        else if (txt.includes('Topología')) renderScreen('09');
        else if (txt.includes('Constructor visual')) renderScreen('08');
        else if (txt.includes('Ajustes')) renderScreen('13');
      };
    }
  });

  // 9. Close tab cross in editor
  document.querySelectorAll('.tab .x').forEach(x => {
    x.style.cursor = 'pointer';
    x.onclick = (e) => {
      e.stopPropagation();
      renderScreen('15');
    };
  });
}

document.addEventListener('DOMContentLoaded', () => {
  // Show demo switcher if ?demo=1 in URL
  const urlParams = new URLSearchParams(window.location.search);
  if (urlParams.get('demo') === '1') {
    document.getElementById('demo-switcher')?.classList.add('visible');
  }

  // Rail navigation
  document.querySelectorAll('.rail a').forEach(a => {
    a.addEventListener('click', (e) => {
      e.preventDefault();
      const targetScreen = a.getAttribute('data-screen');
      if (targetScreen) renderScreen(targetScreen);
    });
  });

  // Status bar "2 problemas" trigger
  const probTrigger = document.getElementById('status-problemas-trigger');
  if (probTrigger) {
    probTrigger.addEventListener('click', toggleBottomPanel);
  }

  // Demo menu builder
  const demoMenu = document.getElementById('demo-menu');
  const demoBtn = document.getElementById('demo-switcher-btn');
  if (demoMenu && demoBtn) {
    demoMenu.innerHTML = Object.values(SCREENS).map(s => `
      <div class="demo-option ${s.id === currentScreenId ? 'selected' : ''}" data-id="${s.id}" onclick="renderScreen('${s.id}'); document.getElementById('demo-menu').classList.remove('open');">
        <span>${s.label}</span>
        <span class="mono" style="font-size:11px;color:var(--muted);">${s.id}</span>
      </div>
    `).join('');

    demoBtn.addEventListener('click', (e) => {
      e.stopPropagation();
      demoMenu.classList.toggle('open');
    });

    document.addEventListener('click', () => {
      demoMenu.classList.remove('open');
    });
  }

  // Keyboard Shortcuts
  window.addEventListener('keydown', (e) => {
    if (e.ctrlKey && e.shiftKey && (e.key === 'P' || e.key === 'p')) {
      e.preventDefault();
      renderScreen('02');
      return;
    }
    if (e.ctrlKey && (e.key === 'O' || e.key === 'o') && !e.shiftKey) {
      e.preventDefault();
      renderScreen('01');
      return;
    }
    if (e.ctrlKey && (e.key === 'N' || e.key === 'n') && !e.shiftKey) {
      e.preventDefault();
      renderScreen('03');
      return;
    }
    if (e.ctrlKey && (e.key === 'J' || e.key === 'j')) {
      e.preventDefault();
      toggleBottomPanel();
      return;
    }
    if (e.key === 'Escape') {
      if (currentScreenId === '02') {
        renderScreen(previousScreenId || '01');
        return;
      }
      if (currentScreenId === '14') {
        renderScreen('03');
        return;
      }
      document.querySelectorAll('.modal-backdrop').forEach(m => m.style.display = 'none');
      document.getElementById('demo-menu')?.classList.remove('open');
    }
  });

  // Route initialization
  const path = window.location.pathname;
  if (path.includes('buscar')) renderScreen('02');
  else if (path.includes('chat') || path.includes('asistente') || path.includes('editor')) renderScreen('03');
  else if (path.includes('constructor')) renderScreen('08');
  else if (path.includes('topologia')) renderScreen('09');
  else if (path.includes('git')) renderScreen('10');
  else if (path.includes('registros') || path.includes('logs')) renderScreen('12');
  else if (path.includes('ajustes')) renderScreen('13');
  else if (path.includes('herramientas')) renderScreen('07');
  else renderScreen('01');
});
